--- Regex-based rules for multi-number and parameterized modifiers
ModTranslationsRU.specialRules = {
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Physical\\ Damage\\ to\\ Attacks\\ and\\ Spells\\ per\\ Siphoning\\ Charge$", replacement = "Добавляет от %1 до %2 физического урона к атакам и чарам за заряд переливания" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Chaos\\ Damage\\ to\\ Attacks$", replacement = "Добавляет от %1 до %2 урона хаосом к атакам" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Chaos\\ Damage\\ to\\ Attacks\\ while\\ you\\ have\\ a\\ Bestial\\ Minion$", replacement = "Добавляет от %1 до %2 урона хаосом к атакам, пока у вас есть приспешник-зверь" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Cold\\ Damage\\ to\\ Attacks$", replacement = "Добавляет от %1 до %2 урона от холода к атакам" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Fire\\ Damage\\ to\\ Attacks$", replacement = "Добавляет от %1 до %2 урона от огня к атакам" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Fire\\ Damage\\ to\\ Attacks\\ with\\ this\\ Weapon\\ per\\ 10\\ Strength$", replacement = "Добавляет от %1 до %2 урона от огня к атакам этим оружием за каждые 10 силы" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Lightning\\ Damage\\ to\\ Attacks$", replacement = "Добавляет от %1 до %2 урона от молнии к атакам" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Lightning\\ Damage\\ to\\ Attacks\\ with\\ this\\ Weapon\\ per\\ 10\\ Dexterity$", replacement = "Добавляет от %1 до %2 урона от молнии атакам этим оружием за каждые 10 ловкости" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Lightning\\ Damage\\ to\\ Attacks\\ with\\ this\\ Weapon\\ per\\ 10\\ Intelligence$", replacement = "Добавляет от %1 до %2 урона от молнии к атакам этим оружием за каждые 10 интеллекта" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Lightning\\ Damage\\ to\\ Unarmed\\ Melee\\ Hits$", replacement = "Добавляет от %1 до %2 урона от молнии к ударам ближнего боя без оружия" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Physical\\ Damage\\ to\\ Attacks$", replacement = "Добавляет от %1 до %2 физического урона к атакам" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Physical\\ Damage\\ to\\ Attacks\\ while\\ you\\ have\\ a\\ Bestial\\ Minion$", replacement = "Добавляет от %1 до %2 физического урона к атакам, пока у вас есть приспешник-зверь" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Physical\\ Damage\\ to\\ Attacks\\ per\\ 25\\ Dexterity$", replacement = "Добавляет от %1 до %2 физического урона к атакам за каждые 25 ловкости" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Physical\\ Damage\\ to\\ Attacks\\ per\\ 25\\ Strength$", replacement = "Добавляет от %1 до %2 физического урона к атакам за каждые 25 силы" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Physical\\ Damage\\ to\\ Attacks\\ per\\ Level$", replacement = "Добавляет от %1 до %2 физического урона к атакам за уровень" },
