    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Cold\\ Damage\\ to\\ Attacks\\ with\\ this\\ Weapon\\ per\\ 10\\ Dexterity$", replacement = "Добавляет от %1 до %2 урона от холода к атакам этим оружием за каждые 10 ловкости" },
    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Cold\\ Damage\\ to\\ Retaliation\\ Skills$", replacement = "Добавляет от %1 до %2 урона от холода умениям расплаты" },
