    { pattern = "^Adds%s+([%+%-]?%d+%.?%d*|%b())%s+to%s+([%+%-]?%d+%.?%d*|%b())%s+Fire\\ Damage\\ if\\ you've\\ Killed\\ Recently$", replacement = "Добавляет от %1 до %2 урона от огня, если вы недавно совершали убийство" },
